import{_ as a,a as t,c as l,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 72 A car called Bluebird","description":"学习 分词修饰与逻辑主语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 72 A car called Bluebird","description":"学习 分词修饰与逻辑主语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 分词修饰与逻辑主语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 71 A famous clock","link":"/life/english/new-concept/book-2/unit-03/lesson-071"},"next":{"text":"第二册：实践与进步 · Lesson 73 The record-holder","link":"/life/english/new-concept/book-2/unit-04/lesson-073"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 71 A famous clock","link":"/life/english/new-concept/book-2/unit-03/lesson-071"},"next":{"text":"第二册：实践与进步 · Lesson 73 The record-holder","link":"/life/english/new-concept/book-2/unit-04/lesson-073"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/lesson-072.md","filePath":"life/english/new-concept/book-2/unit-03/lesson-072.md"}'),r={name:"life/english/new-concept/book-2/unit-03/lesson-072.md"};function o(i,e,s,c,d,h){return t(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-72-a-car-called-bluebird" tabindex="-1">第二册：实践与进步 · Lesson 72 A car called Bluebird <a class="header-anchor" href="#第二册-实践与进步-·-lesson-72-a-car-called-bluebird" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 72 A car called Bluebird&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>试验车挑战纪录时，需要报告尝试次数、可靠性和失败原因；练习定语与命名。本课的语言观察是：a car called ... 中 called 是过去分词后置定语，等于 that is called；它不是主句谓语，所以句子还需要 ran、reached 等谓语。完成学习后，请介绍一台自拟名称的测试设备，给出测试数量和下一步决定。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>engine</td><td>/ˈendʒɪn/</td><td>n.</td><td>发动机</td><td>start an engine</td></tr><tr><td>attempt</td><td>/əˈtempt/</td><td>n.</td><td>尝试</td><td>make an attempt</td></tr><tr><td>powerful</td><td>/ˈpaʊəfəl/</td><td>adj.</td><td>强有力的</td><td>a powerful engine</td></tr><tr><td>average</td><td>/ˈævərɪdʒ/</td><td>n.</td><td>平均值</td><td>on average</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>make an attempt — 作一次尝试</li><li>on average — 平均而言，后文需说明统计范围</li></ul><h2 id="语法讲解-分词修饰与逻辑主语" tabindex="-1">语法讲解：分词修饰与逻辑主语 <a class="header-anchor" href="#语法讲解-分词修饰与逻辑主语" aria-label="Permalink to &quot;语法讲解：分词修饰与逻辑主语&quot;">​</a></h2><p>现在分词常表达主动或正在进行，过去分词常表达被动或完成，用作定语时可置于名词前或以短语形式置后。作状语时，分词的逻辑主语一般要与主句主语一致，否则容易出现悬垂结构。不能只按“现在”“过去”的名称判断时间，具体时态由主句和上下文决定。复杂句改成分词结构前，先确认两个动作的执行者和先后关系。本课应用：a car called ... 中 called 是过去分词后置定语，等于 that is called；它不是主句谓语，所以句子还需要 ran、reached 等谓语。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>A car called Silver Finch completed three test runs.</p></blockquote><p>一辆名为“银雀”的车完成了三次试跑。</p><p>called Silver Finch 修饰 A car，completed 才是主句谓语，three test runs 为宾语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>A car called Silver Finch. 只是名词短语，不构成完整陈述句。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>在 called Silver Finch 后不作句号式停顿，保留主干 car completed 的联系。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>A car called Silver Finch completed three test runs. Its fastest run ended early because of a tyre problem. The team postponed the record attempt.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>介绍一台自拟名称的测试设备，给出测试数量和下一步决定。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：called Silver Finch 修饰 A car，completed 才是主句谓语，three test runs 为宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：A car called Silver Finch. 只是名词短语，不构成完整陈述句。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>句中主句谓语是 called 还是 completed？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> completed</p><p><strong>解析：</strong> called 为后置定语，completed 承担主句谓语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>车队为什么推迟纪录挑战？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Because a tyre problem interrupted the fastest run.</p><p><strong>解析：</strong> 明确原因是轮胎问题，不是发动机功率不足。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将 a car called Silver Finch 展开成定语从句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> a car that is called Silver Finch</p><p><strong>解析：</strong> 过去分词短语可展开为被动定语从句。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：分词修饰与逻辑主语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-071">上一课</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-073">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(r,[["render",o]]);export{u as __pageData,b as default};
